import fs from 'node:fs';
const SEC_B64 = "";
const SEC = Buffer.from(SEC_B64, 'base64').toString('utf8');
const OLD_SUB = Buffer.from("SGF2aWTDrWphcyBrb25zdHJ1a2Npw7MgNiBow7NuYXB0w7NsLCAyIDAwMCB2YWd5IDMgMDAwIGttL2jDsyBrZXJldHRlbC4gQSBrYXVjacOzIGEgYsOpcmzDqXMgdsOpZ8OpbiB2aXNzemFqw6FyLg==","base64").toString("utf8");
const NEW_SUB = Buffer.from("SGF2aWTDrWphcyBlbMWRZml6ZXTDqXNlcyBiw6lybGV0IChBdXRvLUFibyk6IDI3NSBwcsOpbWl1bSBmbG90dGFhdXTDsyBOw6ltZXRvcnN6w6FnYsOzbCwgcsO2dmlkIGZ1dGFtaWTFkXZlbCDDqXMgcnVnYWxtYXMga20ta2VyZXR0ZWwg4oCUIHBsdXN6IHNhasOhdCBiw6lyZWxoZXTFkSBrw6lzemxldMO8bmsuIEEga2F1Y2nDsyBhIGLDqXJsw6lzIHbDqWfDqW4gdmlzc3phasOhci4=","base64").toString("utf8");
const BERL = Buffer.from("IGLDqXJlbGhldMWRIGF1dMOz","base64").toString("utf8");
const SUB_TOTAL = 275;
const FILES = ['dist/autoink/index.html','dist/en/autoink/index.html'];
const ANCHOR = '<div class="autok-panel" id="panel-berelheto">';
let done = 0;
for (const f of FILES) {
  if (!fs.existsSync(f)) continue;
  let h = fs.readFileSync(f, 'utf8');
  if (h.indexOf('sub-filters') > -1) { console.log('[abo] mar beszurva: ' + f); continue; }
  const i = h.indexOf(ANCHOR);
  if (i < 0) { console.log('[abo] nincs panel-berelheto: ' + f); continue; }
  const at = i + ANCHOR.length;
  h = h.slice(0, at) + SEC + h.slice(at);
  if (h.indexOf(OLD_SUB) > -1) h = h.replace(OLD_SUB, NEW_SUB);
  const hb = h.indexOf('data-hero="berelheto"');
  if (hb > -1) { const bi = h.indexOf(BERL, hb); if (bi > -1 && bi < hb + 1600) { let j = bi; while (j > 0 && h[j-1] >= '0' && h[j-1] <= '9') j--; const numStr = h.slice(j, bi); if (numStr) { const n = parseInt(numStr, 10) + SUB_TOTAL; h = h.slice(0, j) + n + h.slice(bi); } } }
  fs.writeFileSync(f, h);
  done++;
  console.log('[abo] beszurva + hero -> ' + f);
}
console.log('[abo] kesz (' + done + ' fajl modositva)');
